with open(config_path, 'r') as f:
    config = yaml.safe_load(f.read())

append = config.get('agent', {}).get('system_prompt_append', '')

# Extract all referenced skill names
all_refs = set()
for match in re.findall(r'→([\w][\w,\s-]+)', append):
    for s in match.split('+'):
        for sub in s.split(','):
            sub = sub.strip().rstrip('|').strip()
            if sub and len(sub) > 2:
                all_refs.add(sub)

# Get all local skill names
skills_dir = "/Users/macpro/.hermes/skills"
local_skills = set()
for root, dirs, files in os.walk(skills_dir):
    if 'SKILL.md' in files:
        name = os.path.basename(os.path.dirname(os.path.join(root, 'SKILL.md')))
        local_skills.add(name)

# Sub-skills loaded via parent (don't need separate routing)
